from content.authoring import E, J, L, P, Q, R, T

LESSONS = [
L('types-variables', 'Values, Types & Variables', 'Store related values and calculate a ticket total.',
  ['A variable has a declared type, a name and a current value. int stores whole numbers; double stores floating-point numbers; boolean stores true or false; char stores one UTF-16 code unit; String stores text. Choose the type from the meaning and range, not from the appearance of one example.',
   'Assignment uses = and replaces the stored value. It does not assert equality. Declare a local variable before using it and assign a value before reading it. Double quotes delimit a String; single quotes delimit a char.',
   'For a ticket receipt, give quantity and unit price readable names, multiply them, then print the result. double is useful for this introduction to decimal arithmetic, but binary floating point is not exact money accounting. The capstone uses bounded whole-number quantities instead.'],
  ['Declare a value with a suitable type.', 'Read and update a variable without confusing = with equality.'],
  E(J('int count = 2;\nint unitPrice = 300;\nint total = count * unitPrice;\nSystem.out.println(total);'), '600\n', ['count stores 2.', 'unitPrice stores 300.', 'total receives the multiplication result.']),
  Q('What is printed after the reassignment?', J('int tickets = 2;\ntickets = 5;\nSystem.out.println(tickets);'), '5', 'The second assignment replaces 2. There is still one tickets variable.'),
  R('Choose types for a whole ticket count, an approximate distance, a yes/no flag and a book title. Explain each.', 'Use int for a bounded whole count, double for approximate distance, boolean for the flag and String for the title.', ['I distinguish text from a single character.', 'I connect each type with its meaning.', 'I describe assignment as storing a value.']),
  P('Declare int quantity = 3 and int price = 120. Calculate total from those variables and print Total: 360.', J('int quantity = 3;\nint price = 120;\nint total = quantity * price;\nSystem.out.println("Total: " + total);'), [T('three items', '', 'Total: 360\n'), T('deterministic receipt', '', 'Total: 360\n')], rubric=['I declare and use quantity and price.', 'I calculate total, rather than hardcoding 360 in the print statement.']),
  diagram={'kind':'memory','nodes':['quantity:int = 3','price:int = 120','quantity × price → total:int = 360'],'edges':[[0,2],[1,2]]}),
L('identifiers-and-naming', 'Names That Explain the Code', 'Use valid identifiers and distinguish scope from spelling.',
  ['An identifier names a class, variable or method. In the simple names used here, start with a letter or underscore and continue with letters, digits or underscores. A name cannot be a Java keyword such as class or int. Java names are case-sensitive: total and Total are different names.',
   'Prefer lowerCamelCase for variables and methods, and UpperCamelCase for classes. Naming conventions improve readability; they are not the same as compiler rules. Avoid cryptic one-letter names except small familiar counters.',
   'Use a name that describes the value and, when needed, its unit: distanceKm or priceCents. A correct spelling does not make an undeclared variable available. More detailed scope rules come with methods.'],
  ['Identify a valid non-keyword identifier.', 'Name a value so another reader can understand its purpose.'],
  E(J('int seatsAvailable = 8;\nSystem.out.println(seatsAvailable);'), '8\n', ['seatsAvailable is declared.', 'The print statement uses the same case.', 'The name explains the value’s role.']),
  Q('Which is a valid variable name: 2tickets, ticketCount, or class?', '', 'ticketCount', '2tickets starts with a digit and class is a keyword. ticketCount follows the course naming convention.'),
  R('Why is distanceKm preferable to d for a user-entered travel distance?', 'The name describes the value and its unit. d may compile but does not communicate the meaning.', ['I distinguish compiler legality from readability.', 'I include meaning and units.']),
  P('Declare remainingSeats = 4 and reservedSeats = 2, calculate availableSeats by subtracting, and print 2.', J('int remainingSeats = 4;\nint reservedSeats = 2;\nint availableSeats = remainingSeats - reservedSeats;\nSystem.out.println(availableSeats);'), [T('available seats', '', '2\n'), T('stable calculation', '', '2\n')], rubric=['I use the three requested readable names.', 'I use consistent capitalization.'])),
L('escape-sequences', 'Escapes Inside Java Strings', 'Create newlines, tabs, quotes and backslashes deliberately.',
  ['A backslash inside a Java String introduces an escape. \\n means a newline, \\t a tab, \\" a quote, and \\\\ one backslash. These are source characters interpreted by Java; they are not extra source-file line breaks.',
   'Do not double an escape accidentally. The Java source "A\\nB" prints two lines; source "A\\\\nB" prints the literal characters A, backslash, n, B. The editor must store real line breaks between source statements while preserving intended escapes inside Strings.',
   'Tabs align to tab stops, not to a fixed number of visible spaces. For a carefully aligned table, use formatting later. For this exercise, exact tab characters are part of the required output.'],
  ['Distinguish source newlines from String escapes.', 'Print quotes, tabs and backslashes correctly.'],
  E(J(r'System.out.println("ITEM\tPRICE");' + '\n' + r'System.out.println("Tea\t120\nCoffee\t150");'), 'ITEM\tPRICE\nTea\t120\nCoffee\t150\n', ['\\t becomes a tab at runtime.', '\\n inside the second String adds a row.', 'println adds the final newline.']),
  Q('Write the output as two lines, without quotes.', J(r'System.out.println("North\nSouth");'), 'North\nSouth', 'One String contains a newline; println adds the ending line break.'),
  R('Explain how to print a double quote and one backslash from a Java String.', 'Escape a quote with backslash-quote; escape one backslash with two source backslashes. The backslash is syntax, not an extra displayed character.', ['I distinguish source spelling from runtime characters.', 'I describe both quote and backslash escapes.']),
  P('Print exactly these two lines: Book: "Orbit" and Path: C:\\books. Use String escapes.', J(r'System.out.println("Book: \"Orbit\"");' + '\n' + r'System.out.println("Path: C:\\books");'), [T('escaped label', '', 'Book: "Orbit"\nPath: C:\\books\n'), T('escaped label again', '', 'Book: "Orbit"\nPath: C:\\books\n')], rubric=['My output includes quotes but no extra backslashes around Orbit.', 'My path has one displayed backslash.']),
  diagram={'kind':'sequence','nodes':['Java source: \\n inside a String','String value: newline character','Console: next line'],'edges':[[0,1],[1,2]]}),
L('arithmetic-integer-division', 'Arithmetic Without Truncation Surprises', 'Group expressions and choose the calculation type before dividing.',
  ['Multiplication, division and remainder have higher precedence than addition and subtraction. Parentheses state the intended grouping. (a + b) / 2 computes an average; a + b / 2 computes a different expression.',
   'When both operands are int, division produces an integer result truncated toward zero. Storing that result in a double afterward does not restore the lost fraction. Make an operand double before dividing, for example / 2.0.',
   'For whole nonnegative quantities, % gives the remainder after division. Division by zero with integers throws an error; a guard will be taught with decisions. This early task uses fixed nonzero divisors, so it does not require untaught branch syntax.'],
  ['Trace expression precedence and parentheses.', 'Avoid integer division when a fractional result is required.'],
  E(J('int a = 5, b = 8;\nSystem.out.println((a + b) / 2);\nSystem.out.println((a + b) / 2.0);'), '6\n6.5\n', ['The sum is computed first.', 'Integer division discards the .5.', '2.0 selects floating-point division.']),
  Q('What exact line does this print?', J('System.out.println(2 + 3 * 4);'), '14', 'Multiplication is evaluated before addition.'),
  R('Why does double average = (5 + 8) / 2 store 6.0 rather than 6.5? Give the repair.', 'The division has integer operands and happens before assignment. Divide by 2.0, or convert an operand to double before division.', ['I name the operand types at division time.', 'I repair before division, not only the result type.']),
  P('Use int a = 3, b = 8. Calculate their decimal average and print 5.5.', J('int a = 3, b = 8;\ndouble average = (a + b) / 2.0;\nSystem.out.println(average);'), [T('odd sum', '', '5.5\n'), T('same calculation', '', '5.5\n')]),
  extra_practice=P('Repair the average so the fractional half is not lost.', J('int a = 5, b = 8;\ndouble average = (a + b) / 2.0;\nSystem.out.println(average);'), [T('fraction preserved', '', '6.5\n'), T('fraction preserved again', '', '6.5\n')], starter=J('int a = 5, b = 8;\ndouble average = (a + b) / 2;\nSystem.out.println(average);'), kind='repair', hints=['Changing only the destination type is insufficient.', 'Make an operand double before division.']),
  diagram={'kind':'sequence','nodes':['a + b: grouped sum','int / int → truncated result','int / double → fractional result'],'edges':[[0,1],[0,2]]}),
L('compound-assignment', 'Update a Stored Value', 'Trace += and increments without losing the old value.',
  ['total += amount updates total using its current value. For these int examples it behaves like total = total + amount. Other arithmetic compound assignments work similarly. Compound assignment has an implicit conversion to the left-hand type; do not use it to hide an inappropriate type choice.',
   'count++ increments count. As a stand-alone statement, ++count has the same final effect. Inside an expression, postfix returns the old value and prefix returns the new one. Prefer separate update statements while learning, so the order stays visible.',
   'A counter tracks how many operations happened. An accumulator tracks a combined result such as a sum. Both need an initial value before any update; upcoming loops will repeat these operations.'],
  ['Trace an accumulator before and after updates.', 'Distinguish prefix and postfix values in a small expression.'],
  E(J('int total = 0;\ntotal += 120;\ntotal += 80;\nSystem.out.println(total);'), '200\n', ['Start at zero.', 'Add 120.', 'Add 80 to the previous total.']),
  Q('Write the two output lines.', J('int n = 2;\nSystem.out.println(n++);\nSystem.out.println(n);'), '2\n3', 'The first println receives the old value; the variable has been incremented by the next statement.'),
  R('Explain the difference between a ticket counter and a sales accumulator.', 'The counter increases by one for each ticket or operation; the accumulator adds each ticket’s amount. Both start from a chosen initial value.', ['I name what each variable measures.', 'I specify its initial value and update.']),
  P('Start points at 10, add 5 with +=, multiply by 2 with *=, subtract 4 with -=, then print the result.', J('int points = 10;\npoints += 5;\npoints *= 2;\npoints -= 4;\nSystem.out.println(points);'), [T('ordered updates', '', '26\n'), T('repeat from initial state', '', '26\n')]),
  diagram={'kind':'memory','nodes':['points = 10','+= 5 → 15','*= 2 → 30','-= 4 → 26'],'edges':[[0,1],[1,2],[2,3]]}),
]
